<?php
namespace App\Http\Controllers\Api\Member\Communications;
use App\Http\Controllers\Controller; use App\Models\InboxMessage; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class InboxController extends Controller { public function index(Request $r):JsonResponse{$q=$r->user()->inboxMessages()->whereNull('archived_at')->latest('published_at');if($r->boolean('unread'))$q->whereNull('read_at');return response()->json(['data'=>$q->paginate(30),'unread_count'=>$r->user()->inboxMessages()->whereNull('read_at')->whereNull('archived_at')->count()]);} public function show(Request $r,InboxMessage $message):JsonResponse{abort_unless($message->user_id===$r->user()->id,403);if(!$message->read_at)$message->update(['read_at'=>now()]);return response()->json(['data'=>$message->fresh()]);} public function read(Request $r,InboxMessage $message):JsonResponse{abort_unless($message->user_id===$r->user()->id,403);$message->update(['read_at'=>now()]);return response()->json(['data'=>$message]);} public function archive(Request $r,InboxMessage $message):JsonResponse{abort_unless($message->user_id===$r->user()->id,403);$message->update(['archived_at'=>now()]);return response()->json(['data'=>$message]);} }
